/***
 * Builds executable CLI commands from package metadata.
 */
export function createUsageFromPackageJson(pkg) {
    if (pkg.bin == null)
        return null;
    if (typeof pkg.bin === 'string') {
        return {
            packageName: pkg.name,
            commands: [
                {
                    name: getPackageBaseName(pkg.name),
                    command: `bunx ${pkg.name}`,
                },
            ],
        };
    }
    const entries = Object.keys(pkg.bin).sort((a, b) => a.localeCompare(b));
    if (entries.length === 0)
        return null;
    if (entries.length === 1) {
        const [name] = entries;
        return {
            packageName: pkg.name,
            commands: [
                {
                    name,
                    command: `bunx ${pkg.name}`,
                },
            ],
        };
    }
    return {
        packageName: pkg.name,
        commands: entries.map((name) => ({
            name,
            command: `bunx ${pkg.name} ${name}`,
        })),
    };
}
/***
 * Extracts the unscoped package name from a package id.
 */
function getPackageBaseName(packageName) {
    return packageName.split('/').pop() ?? packageName;
}
